def apply_evaluation_data(processed_path=PROCESSED_PATH,rubric_path=RUBRIC_PATH):
 d=json.loads(Path(processed_path).read_text(encoding="utf-8"));pages={x["page"]:x for x in d["chunks"]}
 if set(pages)!=set(range(1,55)):raise ValueError("DL PDF 1~54쪽이 필요합니다.")
 d["schema_version"]="2.1.0";d["terminology"]=TERMINOLOGY
 for p in pages:pages[p].update(page_role=role(p),term_ids=[],evidence_units=[],source_issues=[])
 pages[17]["source_issues"]=[{"issue_id":"dl_p17_depth_boundary","source_text":"hidden layer가 2개 이상","issue_type":"overgeneralized","correction":"DNN의 층 수 경계는 문헌과 관습에 따라 달라질 수 있다.","evaluation_policy":"exclude"}]
 pages[29]["source_issues"]=[{"issue_id":"dl_p29_gradient_direction","source_text":"gradient: L(theta)를 가장 빠르게 줄여주는 방향","issue_type":"incorrect","correction":"gradient는 가장 빠른 증가 방향이고 negative gradient가 가장 가파른 하강 방향이다.","evaluation_policy":"exclude"}]
 pages[45]["source_issues"]=[{"issue_id":"dl_p45_batchnorm_explanation","source_text":"internal covariance shift를 해결 / 표준 가우시안 분포로 정규화","issue_type":"overgeneralized","correction":"BatchNorm의 mini-batch 정규화와 학습 가능한 affine transformation을 중심으로 설명한다.","evaluation_policy":"exclude"}]
 pages[46]["source_issues"]=[{"issue_id":"dl_p46_early_stopping_test","source_text":"test 성능 하락","issue_type":"ambiguous","correction":"종료 epoch 선택은 validation set으로 하고 test set은 최종 평가에 보존한다.","evaluation_policy":"warn"}]
 lookup={}
 for raw in UNITS:
  z=dict(raw);p=z.pop("page");pages[p]["term_ids"]=list(dict.fromkeys(pages[p]["term_ids"]+z["term_ids"]));pages[p]["evidence_units"].append(z);lookup[z["unit_id"]]=(pages[p],z)
 Path(processed_path).write_text(json.dumps(d,ensure_ascii=False,indent=2)+"\n",encoding="utf-8");r=build_rubric();claims={c["claim_id"]:c for o in r["top_level_objectives"] for s in o["sub_objectives"] for c in s["claims"]}
 if set(claims)!=set(MAP):raise ValueError(f"Claim mismatch: {set(claims)^set(MAP)}")
 for cid,uids in MAP.items():
  terms=[]
  for uid in uids:
   ch,u=lookup[uid];terms+=u["term_ids"];claims[cid]["evidence"].append({"page":ch["page"],"chunk_id":ch["chunk_id"],"unit_id":uid,"source_excerpt":u["source_excerpt"],"source_status":"verified","review_note":""})
  claims[cid]["term_ids"]=list(dict.fromkeys(terms))
 Path(rubric_path).parent.mkdir(parents=True,exist_ok=True);Path(rubric_path).write_text(json.dumps(r,ensure_ascii=False,indent=2)+"\n",encoding="utf-8")
